scenarios.example_code:
import { emitUsage } from '@projexlight/sdk-meter';
await emitUsage({
  tenant_id, sku: 'vault.encrypt', units: 1,
  dimensions: { app_id, bu_id, persona_id },
  dedup_key: `${trace_id}:vault.encrypt`,
});

// 1. Clone the current catalog to draft
// 2. PUT each new rate via /admin/meter/pricing-catalogs/:catalog_id/rates/:sku
// 3. Flip status to 'published'
await fetch(`${gw}/admin/meter/pricing-catalogs/${draft_id}/status`, { method: 'POST', body: JSON.stringify({ status: 'published' }) });

// Middleware at the gateway calls into soft-cap check automatically.
// If exceeded:
// response.headers['x-projex-meter-warn'] = 'softcap-exceeded:vault.encrypt'
// Listen via:
subscribeEvents('meter.softcap.exceeded.v1', async (e) => {
  await notifyTenantAdmin(e.tenant_id, e.payload.sku, e.payload.current, e.payload.cap);
});

// Middleware DENIES the call:
// HTTP 429 + body: { error: 'QuotaExceeded', sku: 'vault.encrypt', cap: 10000, current: 10001 }
// Caller catches and either backs off or surfaces to the customer.

// Runs automatically when METER_VERIFIER_INTERVAL_MS is set (default 24h).
